-- SCHEMA
-- ============================================================================


CREATE TABLE ref_carrier_service (
    gkey BIGINT PRIMARY KEY,
    id VARCHAR(50) NOT NULL UNIQUE,
    name VARCHAR(200),
    INDEX idx_service_id (id)
) ENGINE=InnoDB;

CREATE TABLE ref_equip_type (
    gkey BIGINT PRIMARY KEY,
    id VARCHAR(50) NOT NULL,
    archetype BIGINT,
    basic_length VARCHAR(20),
    nominal_height VARCHAR(20),
    iso_code VARCHAR(10),
    INDEX idx_equip_type (id)
) ENGINE=InnoDB;

CREATE TABLE ref_equipment (
    gkey BIGINT PRIMARY KEY,
    id VARCHAR(50) NOT NULL,
    eqtyp_gkey BIGINT,
    INDEX idx_equipment_id (id)
) ENGINE=InnoDB;

CREATE TABLE vsl_vessels (
    gkey BIGINT PRIMARY KEY,
    id VARCHAR(50) NOT NULL UNIQUE,
    name VARCHAR(200) NOT NULL,
    imo_nbr VARCHAR(20),
    lloyds_id VARCHAR(50),
    gross_registered_tonnage DECIMAL(12,2),
    length_overall DECIMAL(10,2),
    beam DECIMAL(10,2),
    INDEX idx_vessel_name (name)
) ENGINE=InnoDB;

CREATE TABLE argo_visit_details (
    gkey BIGINT PRIMARY KEY,
    eta DATETIME NULL,
    etd DATETIME NULL,
    ata DATETIME NULL,
    atd DATETIME NULL,
    service BIGINT,
    INDEX idx_eta (eta),
    INDEX idx_ata (ata)
) ENGINE=InnoDB;

CREATE TABLE argo_carrier_visit (
    gkey BIGINT PRIMARY KEY,
    id VARCHAR(50) NOT NULL UNIQUE,
    carrier_mode VARCHAR(20) DEFAULT 'VESSEL',
    phase VARCHAR(20) NOT NULL,
    ata DATETIME NULL,
    atd DATETIME NULL,
    cvcvd_gkey BIGINT,
    INDEX idx_visit_id (id),
    INDEX idx_phase (phase),
    INDEX idx_ata (ata)
) ENGINE=InnoDB;

CREATE TABLE vsl_vessel_visit_details (
    vvd_gkey BIGINT PRIMARY KEY,
    vessel_gkey BIGINT NOT NULL,
    INDEX idx_vessel (vessel_gkey)
) ENGINE=InnoDB;

CREATE TABLE xps_che (
    gkey BIGINT PRIMARY KEY,
    id VARCHAR(50) NOT NULL UNIQUE,
    full_name VARCHAR(100) NOT NULL,
    kind_enum VARCHAR(20) NOT NULL,
    active TINYINT(1) DEFAULT 1,
    INDEX idx_che_name (full_name),
    INDEX idx_che_kind (kind_enum)
) ENGINE=InnoDB;

CREATE TABLE inv_unit (
    gkey BIGINT PRIMARY KEY,
    id VARCHAR(50) NOT NULL,
    category VARCHAR(20),
    freight_kind VARCHAR(20),
    eq_gkey BIGINT,
    requires_power TINYINT(1) DEFAULT 0,
    is_hazardous TINYINT(1) DEFAULT 0,
    line_id VARCHAR(50),
    INDEX idx_unit_id (id),
    INDEX idx_category (category),
    INDEX idx_line (line_id)
) ENGINE=InnoDB;

CREATE TABLE inv_unit_fcy_visit (
    gkey BIGINT PRIMARY KEY,
    unit_gkey BIGINT NOT NULL,
    transit_state VARCHAR(20),
    time_in DATETIME NULL,
    time_out DATETIME NULL,
    last_pos_slot VARCHAR(50),
    last_pos_loctype VARCHAR(20),
    last_pos_locid VARCHAR(50),
    intend_ob_cv BIGINT,
    declrd_ib_cv BIGINT,
    INDEX idx_unit (unit_gkey),
    INDEX idx_transit_state (transit_state),
    INDEX idx_time_in (time_in)
) ENGINE=InnoDB;

CREATE TABLE inv_unit_yrd_visit (
    gkey BIGINT PRIMARY KEY,
    ufv_gkey BIGINT NOT NULL,
    INDEX idx_ufv (ufv_gkey)
) ENGINE=InnoDB;

CREATE TABLE inv_wi (
    gkey BIGINT PRIMARY KEY,
    uyv_gkey BIGINT,
    move_kind VARCHAR(10),
    move_stage VARCHAR(20),
    carrier_locid VARCHAR(50),
    INDEX idx_move_kind (move_kind),
    INDEX idx_carrier (carrier_locid)
) ENGINE=InnoDB;

CREATE TABLE inv_move_event (
    gkey BIGINT PRIMARY KEY,
    ufv_gkey BIGINT,
    move_kind VARCHAR(10),
    move_stage VARCHAR(20),
    category VARCHAR(20),
    freight_kind VARCHAR(20),
    restow_reason VARCHAR(50),
    t_fetch DATETIME NULL,
    t_put DATETIME NULL,
    t_discharge DATETIME NULL,
    che_fetch BIGINT,
    che_put BIGINT,
    che_qc BIGINT,
    fm_pos_slot VARCHAR(50),
    fm_pos_loctype VARCHAR(20),
    fm_pos_locid VARCHAR(50),
    to_pos_slot VARCHAR(50),
    to_pos_loctype VARCHAR(20),
    to_pos_locid VARCHAR(50),
    length_mm INT,
    twin_put TINYINT(1) DEFAULT 0,
    twin_fetch TINYINT(1) DEFAULT 0,
    INDEX idx_move_kind (move_kind),
    INDEX idx_t_fetch (t_fetch),
    INDEX idx_t_put (t_put),
    INDEX idx_t_discharge (t_discharge),
    INDEX idx_fm_locid (fm_pos_locid),
    INDEX idx_to_locid (to_pos_locid),
    INDEX idx_che_fetch (che_fetch),
    INDEX idx_che_put (che_put),
    INDEX idx_che_qc (che_qc)
) ENGINE=InnoDB;

CREATE TABLE road_truck_transactions (
    gkey BIGINT PRIMARY KEY,
    unit_gkey BIGINT,
    truck_license_nbr VARCHAR(50),
    sub_type VARCHAR(10),
    status VARCHAR(20) DEFAULT 'COMPLETE',
    handled DATETIME,
    time_in DATETIME NULL,
    time_out DATETIME NULL,
    ctr_id VARCHAR(50),
    ctr_freight_kind VARCHAR(20),
    ctr_type_id VARCHAR(10),
    eqo_eq_length INT,
    temp_required DECIMAL(5,2),
    is_hazard TINYINT(1) DEFAULT 0,
    line_id VARCHAR(50),
    declrd_ib_cv BIGINT,
    intend_ob_cv BIGINT,
    INDEX idx_truck (truck_license_nbr),
    INDEX idx_time_in (time_in),
    INDEX idx_time_out (time_out),
    INDEX idx_handled (handled),
    INDEX idx_sub_type (sub_type)
) ENGINE=InnoDB;

CREATE TABLE argo_yard (
    gkey BIGINT PRIMARY KEY,
    abm_gkey BIGINT NOT NULL,
    fcy_gkey BIGINT NOT NULL,
    name VARCHAR(100) NOT NULL
) ENGINE=InnoDB;

CREATE TABLE spatial_bins (
    gkey BIGINT PRIMARY KEY,
    parent_bin_gkey BIGINT,
    bin_level INT,
    bin_subclass VARCHAR(10),
    internal_pos_name VARCHAR(50),
    internal_pos_name_alt VARCHAR(50),
    block_type_enum VARCHAR(20),
    z_index_first INT,
    z_index_last INT,
    life_cycle_state VARCHAR(10) DEFAULT 'ACT',
    INDEX idx_bin_level (bin_level),
    INDEX idx_internal_pos (internal_pos_name)
) ENGINE=InnoDB;

CREATE TABLE spatial_bin_ancestors (
    gkey BIGINT PRIMARY KEY,
    bin_gkey BIGINT NOT NULL,
    ancestor_bin_gkey BIGINT NOT NULL,
    bin_level INT,
    ancestor_bin_level INT,
    life_cycle_state VARCHAR(10) DEFAULT 'ACT',
    INDEX idx_bin (bin_gkey),
    INDEX idx_ancestor (ancestor_bin_gkey)
) ENGINE=InnoDB;

CREATE TABLE xps_stackstatus (
    gkey BIGINT PRIMARY KEY,
    bin BIGINT NOT NULL,
    status_chars VARCHAR(10),
    INDEX idx_bin (bin)
) ENGINE=InnoDB;

