-- VIEWS
-- ============================================================================


CREATE OR REPLACE VIEW v_active_vessels AS
SELECT
    v.name AS vessel_name,
    acv.id AS visit_id,
    acv.phase,
    avd.eta,
    avd.ata,
    avd.etd,
    rcs.name AS service_name
FROM argo_carrier_visit acv
LEFT JOIN argo_visit_details avd ON avd.gkey = acv.cvcvd_gkey
LEFT JOIN vsl_vessel_visit_details vvd ON vvd.vvd_gkey = avd.gkey
LEFT JOIN vsl_vessels v ON v.gkey = vvd.vessel_gkey
LEFT JOIN ref_carrier_service rcs ON rcs.gkey = avd.service
WHERE acv.carrier_mode = 'VESSEL'
AND acv.phase IN ('30ARRIVED','40WORKING','50COMPLETE');

CREATE OR REPLACE VIEW v_yard_occupancy AS
SELECT
    iu.category,
    CASE WHEN iu.requires_power = 1 THEN 'REEFER' ELSE 'DRY' END AS container_type,
    COUNT(*) AS units,
    SUM(CASE
        WHEN ret.basic_length = 'BASIC20' THEN 1.0
        WHEN ret.basic_length = 'BASIC40' THEN 2.0
        WHEN ret.basic_length = 'BASIC45' THEN 2.25
        ELSE 1.0
    END) AS teus
FROM inv_unit iu
JOIN inv_unit_fcy_visit iufv ON iufv.unit_gkey = iu.gkey
JOIN ref_equipment req ON req.gkey = iu.eq_gkey
JOIN ref_equip_type ret ON ret.gkey = req.eqtyp_gkey
WHERE iufv.transit_state = 'S40_YARD'
GROUP BY iu.category, container_type;

CREATE OR REPLACE VIEW v_che_productivity AS
SELECT
    che.full_name,
    che.kind_enum,
    DATE(ime.t_put) AS work_date,
    COUNT(*) AS total_moves,
    COUNT(DISTINCT HOUR(ime.t_put)) AS working_hours
FROM inv_move_event ime
JOIN xps_che che ON che.gkey = COALESCE(ime.che_put, ime.che_fetch)
WHERE ime.t_put >= DATE_SUB(CURDATE(), INTERVAL 7 DAY)
GROUP BY che.full_name, che.kind_enum, DATE(ime.t_put);

SET TIME_ZONE=@OLD_TIME_ZONE;
SET SQL_MODE=@OLD_SQL_MODE;
SET FOREIGN_KEY_CHECKS = 1;

