CREATE TABLE ref_crane_delay_types (
    gkey BIGINT PRIMARY KEY,
    id VARCHAR(20) NOT NULL,
    description VARCHAR(200) NOT NULL,
    delay_category VARCHAR(50),
    INDEX idx_category (delay_category)
) ENGINE=InnoDB;

CREATE TABLE vsl_crane_statistics (
    gkey BIGINT PRIMARY KEY,
    vvd_gkey BIGINT NOT NULL,
    crane_gkey BIGINT NOT NULL,
    INDEX idx_vvd (vvd_gkey),
    INDEX idx_crane (crane_gkey)
) ENGINE=InnoDB;

CREATE TABLE vsl_crane_statistics_delays (
    gkey BIGINT PRIMARY KEY,
    cstat_gkey BIGINT NOT NULL,
    crane_delay_type_gkey BIGINT NOT NULL,
    delay_date DATETIME NOT NULL,
    time INT NOT NULL,
    INDEX idx_cstat (cstat_gkey),
    INDEX idx_delay_type (crane_delay_type_gkey),
    INDEX idx_date (delay_date)
) ENGINE=InnoDB;


