UNION ALL SELECT 'Vessel Visits', COUNT(*) FROM argo_carrier_visit
UNION ALL SELECT 'Container Moves', COUNT(*) FROM inv_move_event
UNION ALL SELECT 'Work Instructions', COUNT(*) FROM inv_wi
UNION ALL SELECT 'Container Units', COUNT(*) FROM inv_unit
UNION ALL SELECT 'Gate Transactions', COUNT(*) FROM road_truck_transactions
UNION ALL SELECT 'CHE Equipment', COUNT(*) FROM xps_che
UNION ALL SELECT 'Yard Slots', COUNT(*) FROM spatial_bins WHERE bin_level = 4
UNION ALL SELECT 'Carrier Services', COUNT(*) FROM ref_carrier_service;

SELECT phase, COUNT(*) AS visits FROM argo_carrier_visit GROUP BY phase ORDER BY phase;
SELECT kind_enum, COUNT(*) AS units FROM xps_che GROUP BY kind_enum ORDER BY kind_enum;
